SELECT ws.ws_order_number, ws.ws_item_sk, i.i_product_name, ws.ws_bill_customer_sk, date_add('day', ws.ws_sold_date_sk, DATE '1970-01-01') AS sale_date, ws.ws_quantity, ws.ws_net_profit, ROUND(ws.ws_net_profit / NULLIF(SUM(ws.ws_net_profit) OVER (PARTITION BY ws.ws_item_sk), 0), 4) AS profit_share_per_item, SUM(ws.ws_quantity) OVER (PARTITION BY ws.ws_bill_customer_sk ORDER BY ws.ws_sold_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity_by_customer, CASE WHEN ws.ws_net_profit < 0 THEN 'Negative' WHEN ws.ws_net_profit BETWEEN 0 AND 100 THEN 'Low' WHEN ws.ws_net_profit BETWEEN 100 AND 500 THEN 'Medium' ELSE 'High' END AS profit_category, p.p_promo_name, hd.hd_vehicle_count FROM web_sales ws INNER JOIN item i ON ws.ws_item_sk = i.i_item_sk LEFT JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk LEFT JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk WHERE ws.ws_quantity > 0 ORDER BY ws.ws_bill_customer_sk, ws.ws_sold_date_sk
